"}, {"path": "questions/question.py", "content": """"Question entity and answer checking for Space Fractions.

Answers are checked with :class:`fractions.Fraction` so that equivalent
forms (e.g. 2/4 == 1/2) are accepted for typed answers.
"""
from dataclasses import dataclass, field
from enum import Enum
from fractions import Fraction
from typing import List, Optional, Tuple


class QuestionType(str, Enum):
    """The four fraction question types in the game."""
    EQUIVALENT = "equivalent"
    COMPARE = "compare"
    ADD_SUBTRACT = "add_subtract"
    SIMPLIFY = "simplify"


@dataclass
class Question:
    """A single fraction question.

    Attributes mirror the UML class diagram: ``id``, ``prompt``, ``options``
    plus the additional fields needed to actually check an answer.
    """
    id: str
    prompt: str
    options: List[str] = field(default_factory=list)
    qtype: QuestionType = QuestionType.EQUIVALENT
    answer: str = "1/2"
    #: True -> multiple choice; False -> typed (numeric) answer.
    is_choice: bool = True

    # --- UML methods -------------------------------------------------------
    def getPrompt(self) -> str:
        return self.prompt

    def getOptions(self) -> List[str]:
        return list(self.options)

    # --- answer checking ---------------------------------------------------
    @staticmethod
    def _parse_fraction(value: str) -> Fraction:
        value = (value or "").strip()
        if "/" in value:
            num, den = value.split("/", 1)
            return Fraction(int(num.strip()), int(den.strip()))
        return Fraction(int(value))

    def checkAnswer(self, submitted: Optional[str]) -> Tuple[bool, str]:
        """Return ``(correct, expected_canonical)``.

        For compare questions the expected answer is one of the given options;
        for all other types the answer is reduced to canonical form so that
        e.g. ``2/4`` matches ``1/2``.
        """
        submitted = (submitted or "").strip()
        if not submitted:
            return False, self._canonical_answer()
        if self.qtype is QuestionType.COMPARE:
            return submitted == self.answer, self.answer
        try:
            return (
                self._parse_fraction(submitted) == self._parse_fraction(self.answer),
                self._canonical_answer(),
            )
        except (ValueError, ZeroDivisionError):
            return False, self._canonical_answer()

    def _canonical_answer(self) -> str:
        try:
            f = self._parse_fraction(self.answer)
            return f"{f.numerator}/{f.denominator}"
        except (ValueError, ZeroDivisionError):
            return self.answer
"}]}

{"files": [{"path": "questions/repository.py", "content": """"Question persistence: load from a JSON file (data/questions.json).

Also exposes in-memory add/update/delete for the admin use case.
"""
import json
import random
from pathlib import Path
from typing import List, Optional

from .question import Question, QuestionType

_PACKAGE_DIR = Path(__file__).resolve().parent
PROJECT_ROOT = _PACKAGE_DIR.parent
DEFAULT_DATA_FILE = PROJECT_ROOT / "data" / "questions.json"

QTYPE_BY_NAME = {qt.value: qt for qt in QuestionType}


def _question_from_dict(d: dict) -> Question:
    return Question(
        id=str(d["id"]),
        prompt=d["prompt"],
        options=list(d.get("options", [])),
        qtype=QTYPE_BY_NAME[d.get("type", "equivalent")],
        answer=str(d.get("answer", "")),
        is_choice=bool(d.get("is_choice", True)),
    )


def _question_to_dict(q: Question) -> dict:
    return {
        "id": q.id,
        "prompt": q.prompt,
        "options": list(q.options),
        "type": q.qtype.value,
        "answer": q.answer,
        "is_choice": q.is_choice,
    }


class QuestionRepository:
    """Load, cache and mutate the question bank (stdin of admin use case)."""

    def __init__(self, data_file: Optional[Path] = None):
        self.data_file = Path(data_file) if data_file else DEFAULT_DATA_FILE
        self._questions: List[Question] = []
        self.load()

    def load(self) -> None:
        with self.data_file.open("r", encoding="utf-8") as fh:
            raw = json.load(fh)
        items = raw if isinstance(raw, list) else raw.get("questions", [])
        self._questions = [_question_from_dict(d) for d in items]

    def save(self) -> None:
        data = [_question_to_dict(q) for q in self._questions]
        self.data_file.parent.mkdir(parents=True, exist_ok=True)
        with self.data_file.open("w", encoding="utf-8") as fh:
            json.dump(data, fh, indent=2)

    # --- queries -----------------------------------------------------------
    def all(self) -> List[Question]:
        return list(self._questions)

    def count(self) -> int:
        return len(self._questions)

    def get(self, question_id: str) -> Optional[Question]:
        for q in self._questions:
            if q.id == str(question_id):
                return q
        return None

    def sample(self, n: int, rng: Optional[random.Random] = None) -> List[Question]:
        """Return a random round of ``n`` questions (without repeats when possible)."""
        rng = rng or random
        pool = list(self._questions)
        rng.shuffle(pool)
        return pool[:n]

    # --- admin mutations ---------------------------------------------------
    def add(self, question: Question) -> None:
        self._questions.append(question)

    def update(self, question: Question) -> None:
        for i, q in enumerate(self._questions):
            if q.id == question.id:
                self._questions[i] = question
                return
        self._questions.append(question)

    def delete(self, question_id: str) -> bool:
        before = len(self._questions)
        self._questions = [q for q in self._questions if q.id != str(question_id)]
        return len(self._questions) != before
"}]}

{"files": [{"content": """"The Game aggregate: state machine, scoring, and per-question flow.

Mirrors the UML ``Game`` class (id, score; play(), viewScore()) while adding
the pause/resume/gameOver transitions from the state diagram.
"""
from dataclasses import dataclass, field
from typing import List, Optional, Tuple

from game.state import GameState, can_transition
from questions.question import Question

ROUND_SIZE = 10


@dataclass
class GameResult:
    """Final result of a finished game."""
    score: int
    total: int
    correct: int
    percentage: int
    stars: int


@dataclass
class Game:
    """A single play-through of ``ROUND_SIZE`` questions."""
    id: str = ""
    score: int = 0
    _state: GameState = GameState.PLAYING
    questions: List[Question] = field(default_factory=list)
    current_index: int = 0
    correct_count: int = 0

    # --- state machine -----------------------------------------------------
    @property
    def state(self) -> GameState:
        return self._state

    def _transition(self, target: GameState) -> None:
        if not can_transition(self._state, target):
            raise ValueError(
                f"Invalid transition '{self._state.value}' -> '{target.value}'"
            )
        self._state = target

    def pause(self) -> None:
        self._transition(GameState.PAUSED)

    def resume(self) -> None:
        self._transition(GameState.PLAYING)

    def gameOver(self) -> None:
        self._transition(GameState.GAMEOVER)

    # --- UML methods -------------------------------------------------------
    def play(self) -> None:
        """Start (or continue) the round."""
        self._state = GameState.PLAYING

    def viewScore(self) -> int:
        return self.score

    # --- round flow --------------------------------------------------------
    @property
    def current_question(self) -> Optional[Question]:
        if self.current_index >= len(self.questions):
            return None
        return self.questions[self.current_index]

    @property
    def total_questions(self) -> int:
        return len(self.questions)

    @property
    def question_number(self) -> int:
        """1-based number of the question being answered."""
        return min(self.current_index + 1, self.total_questions)

    def submit(self, answer: Optional[str]) -> Tuple[bool, str]:
        """Submit the answer for the current question; advance to next.

        Returns ``(correct, expected_canonical)`` computed BEFORE advancing.
        Raises ValueError if the game is not currently Playing.
        """
        if self._state is not GameState.PLAYING:
            raise ValueError("Cannot submit while paused or over")
        q = self.current_question
        if q is None:
            raise ValueError("No current question to answer")
        correct, expected = q.checkAnswer(answer)
        if correct:
            self.score += 1
            self.correct_count += 1
        self.current_index += 1
        if self.current_index >= len(self.questions):
            self._state = GameState.GAMEOVER
        return correct, expected

    def result(self) -> GameResult:
        total = self.total_questions
        pct = 0 if total == 0 else round(100 * self.score / total)
        if pct >= 95:
            stars = 3
        elif pct >= 80:
            stars = 2
        elif pct >= 60:
            stars = 1
        else:
            stars = 0
        return GameResult(
            score=self.score,
            total=total,
            correct=self.correct_count,
            percentage=pct,
            stars=stars,
        )
"}]}

